function status = mergeSleepData(projectDir,outDir,AP_MQCT,uiPgDlg,exclusions)
%GENSITTOSTANDTABLE merge sleep-data generated by ActiPASS bedtime/sleep module into one table

% INPUTS
% projectDir [string]: ActiPASS project folder
% outDir [string]: Output directory
% AP_MQCT [table]: ActiPASS master QC table
% uiPgDlg: progress dialog or object (Value, Message, CancelRequested)
% exclusions [string, optional]: files left out by QC_Status: "NotOK" (default, as before),
%   "Check+NotOK" (only OK files) or "None" (all files)

% OUTPUT
% status [string]: "OK": everything went well, "Check": only some files processed,  "Error": none of the files processed


% Copyright (c) 2024, Pasan Hettiarachchi
% pasan.hettiarachchi@medsci.uu.se
% All rights reserved.
%
% Redistribution and use in source and binary forms, with or without
% modification, are permitted provided that the following conditions are met:
% 1. Redistributions of source code must retain the above copyright notice,
%    this list of conditions and the following disclaimer.
% 2. Redistributions in binary form must reproduce the above copyright notice,
%    this list of conditions and the following disclaimer in the documentation
%    and/or other materials provided with the distribution.
% 3. Neither the name of the copyright holder nor the names of its contributors
%    may be used to endorse or promote products derived from this software without
%    specific prior written permission.
%
% THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS "AS IS"
% AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE
% IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE
% ARE DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDER OR CONTRIBUTORS BE
% LIABLE FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR
% CONSEQUENTIAL DAMAGES (INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF
% SUBSTITUTE GOODS OR SERVICES; LOSS OF USE, DATA, OR PROFITS; OR BUSINESS
% INTERRUPTION) HOWEVER CAUSED AND ON ANY THEORY OF LIABILITY, WHETHER IN
% CONTRACT, STRICT LIABILITY, OR TORT (INCLUDING NEGLIGENCE OR OTHERWISE)
% ARISING IN ANY WAY OUT OF THE USE OF THIS SOFTWARE, EVEN IF ADVISED OF THE
% POSSIBILITY OF SUCH DAMAGE.




% leave out files by their QC_Status (default: NotOK files, as before)
if nargin<5 || isempty(exclusions), exclusions="NotOK"; end
if exclusions=="NotOK"
    AP_MQCT(AP_MQCT.QC_Status=="NotOK",:)=[]; % delete cases where QC_Status is NotOK
elseif exclusions=="Check+NotOK"
    AP_MQCT(AP_MQCT.QC_Status~="OK",:)=[]; % only OK files
elseif exclusions~="None"
    error("exclusions must be None, NotOK or Check+NotOK");
end

mergedT=[];

%count non problamatic files
doneFs=0;

% create a table to hole processing errors (so we can process the next file)
ProcErrT=[AP_MQCT(:,"SubjectID"),table('size',[height(AP_MQCT),1],'VariableTypes',["string"],'VariableNames',["processing_error"])];

% iterate through files
for itrFil=1:height(AP_MQCT)
    try
        % check for cancelation
        if uiPgDlg.CancelRequested
            status="Cancelled";
            return;
        end
        
        % find the ID of this person
        subjctID=AP_MQCT.SubjectID(itrFil);
        
        % location of per-second-table
        perSecF=fullfile(projectDir,"IndividualOut",subjctID,subjctID+" - bedtime.csv");
        
        % update progress dialog
        uiPgDlg.Value=(itrFil-1)/height(AP_MQCT)+(1/height(AP_MQCT))*0.1;
        uiPgDlg.Message="Processing: ID: "+subjctID+". File "+itrFil+" of "+height(AP_MQCT)+"..";
        
        % load data from mat file
        sleepT = readtable(perSecF,'TextType',"string",'DatetimeType',"text");
        if ~isempty(sleepT)
            if ~isempty(mergedT)
                mergedT=vertcat(mergedT,sleepT);
            else
                mergedT=sleepT;
            end
        end
      
        % check for cancelation
        if uiPgDlg.CancelRequested
            status="Cancelled";
            return;
        end
        
        doneFs=doneFs+1;
        ProcErrT.processing_error(itrFil)="none";
    catch ME
        % if there are errors still continue
        msgTxt=getReport(ME,'extended','hyperlinks','off');
        ProcErrT.processing_error(itrFil)=msgTxt;
        continue;
    end
end

% write any errors during processing to disk
writetable(ProcErrT,fullfile(outDir,"Processing errors.xlsx"),'WriteMode','replacefile');

if ~isempty(mergedT)
    % write all transitions data to the sit-to-stand master-file
    writetable(mergedT,fullfile(outDir,"Merged_SleepData.csv"));
end

% update the status field
if doneFs==height(AP_MQCT)
    status="OK";
elseif doneFs>=1
    status="Check";
elseif doneFs==0
    status="Error";
end

end

